export function ResourceCalendar({
  date = "{{date}}",
  resource1 = "{{resource1}}",
  resource2 = "{{resource2}}",
  density = "{{density}}",
  accent = "{{accent}}",
}) {
  const pad = density === "Compact" ? "4px 10px" : "9px 10px";
  const cellStyle = { border: "1px solid #24143018", padding: pad, textAlign: "left" };
  const rows = [
    { time: "9:00", booked: 0 },
    { time: "10:00", booked: 1 },
    { time: "11:00", booked: 2 },
  ];
  const resources = [resource1, resource2, "Room C"];
  return (
    <table style={{ borderCollapse: "collapse", width: 460, font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <caption style={{ textAlign: "left", fontWeight: 700, paddingBottom: 10 }}><time dateTime={date}>{date}</time></caption>
      <thead>
        <tr>
          <th scope="col" style={{ ...cellStyle, background: "#24143008", fontWeight: 700 }}>Time</th>
          {resources.map((r) => <th key={r} scope="col" style={{ ...cellStyle, background: "#24143008", fontWeight: 700 }}>{r}</th>)}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.time}>
            <th scope="row" style={{ ...cellStyle, fontWeight: 500, color: "#24143099", fontVariantNumeric: "tabular-nums" }}>{row.time}</th>
            {resources.map((r, i) => (
              <td key={r} style={i === row.booked ? { ...cellStyle, fontWeight: 700, background: accent } : cellStyle}>
                {i === row.booked ? "Booked" : "Free"}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
